//! Optional creation metadata over the SAME relationship intent/write rows.
//! The returned GroupID is private; history and stored booleans never mint the
//! one-shot current property READ brand. No automatic retry or roster seeding.
use super::{group_create::{CreateInput,CreatedReply},group_management::GroupWriteOperation,group_management_store::Descriptor};
use rusqlite::{Connection,params,OptionalExtension};
const STORAGE:&str="app_account_relation_storage_failed";
pub(super) fn installed(c:&Connection)->Result<bool,&'static str>{c.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='app_voice_group_creations')",[],|r|r.get(0)).map_err(|_|STORAGE)}
pub(super) fn initialize_schema(c:&Connection)->Result<(),&'static str>{
 // The existing management descriptor schema stays byte-compatible. Creation
 // gets its own optional descriptor, but NOT a second intent/exclusion journal.
 super::group_management_store::initialize_schema(c)?;
 c.execute_batch("CREATE TABLE IF NOT EXISTS app_voice_group_creations(
 line_id TEXT NOT NULL,user_nonce TEXT NOT NULL CHECK(length(user_nonce)=32),intent_id INTEGER NOT NULL CHECK(intent_id>0),write_id INTEGER CHECK(write_id>0),properties INTEGER NOT NULL CHECK(properties BETWEEN 2 AND 128),initial_members INTEGER NOT NULL CHECK(initial_members BETWEEN 1 AND 128),read_properties INTEGER NOT NULL CHECK(read_properties IN(0,1)),body_hash BLOB NOT NULL CHECK(typeof(body_hash)='blob' AND length(body_hash)=32),group_id BLOB CHECK(group_id IS NULL OR(typeof(group_id)='blob' AND length(group_id) BETWEEN 1 AND 508)),reply_hash BLOB CHECK(reply_hash IS NULL OR(typeof(reply_hash)='blob' AND length(reply_hash)=32)),relation_type INTEGER CHECK(relation_type BETWEEN 0 AND 4294967295),relation_properties INTEGER CHECK(relation_properties BETWEEN 0 AND 128),PRIMARY KEY(line_id,user_nonce));").map_err(|_|STORAGE)
}
pub(super) fn capture_input(c:&Connection,line:&str,nonce:&str,input:&CreateInput,intent:i64)->Result<(),&'static str>{
 if !installed(c)?{return Err("app_account_group_create_not_installed");}c.execute("INSERT INTO app_voice_group_creations(line_id,user_nonce,intent_id,properties,initial_members,read_properties,body_hash) VALUES(?1,?2,?3,?4,?5,?6,?7)",params![line,nonce,intent,input.property_count as i64,input.initial_members as i64,i64::from(input.read_properties),input.fingerprint().as_slice()]).map_err(|_|STORAGE)?;Ok(())
}
pub(super) fn require_input(c:&Connection,line:&str,nonce:&str,intent:i64,input:&CreateInput)->Result<(),&'static str>{
 let yes:bool=c.query_row("SELECT EXISTS(SELECT 1 FROM app_voice_group_creations d WHERE d.line_id=?1 AND d.user_nonce=?2 AND d.intent_id=?3 AND d.body_hash=?4 AND d.properties=?5 AND d.initial_members=?6 AND d.read_properties=?7 AND NOT EXISTS(SELECT 1 FROM app_voice_group_write_operations m WHERE m.line_id=d.line_id AND m.user_nonce=d.user_nonce))",params![line,nonce,intent,input.fingerprint().as_slice(),input.property_count as i64,input.initial_members as i64,i64::from(input.read_properties)],|r|r.get(0)).map_err(|_|STORAGE)?;
 if yes{Ok(())}else{Err(STORAGE)}
}
pub(super) fn bind(c:&Connection,line:&str,nonce:&str,d:Descriptor,intent:Option<i64>,write:Option<i64>)->Result<(),&'static str>{
 if get(c,line,nonce,intent,None)?!=Some(d){return Err(STORAGE);}if let Some(write)=write{let n=c.execute("UPDATE app_voice_group_creations SET write_id=?3 WHERE line_id=?1 AND user_nonce=?2 AND (write_id IS NULL OR write_id=?3)",params![line,nonce,write]).map_err(|_|STORAGE)?;if n!=1{return Err(STORAGE);}}Ok(())
}
pub(super) fn get(c:&Connection,line:&str,nonce:&str,intent:Option<i64>,write:Option<i64>)->Result<Option<Descriptor>,&'static str>{
 if !installed(c)?{return Ok(None);}let row:Option<(i64,i64,Option<i64>,i64,i64,Option<i64>)>=c.query_row("SELECT d.properties,d.intent_id,d.write_id,d.initial_members,d.read_properties,CASE WHEN typeof(d.body_hash)='blob' AND length(d.body_hash)=32 AND EXISTS(SELECT 1 FROM app_voice_relation_intents i WHERE i.id=d.intent_id AND i.line_id=d.line_id AND i.user_nonce=d.user_nonce AND i.body_hash=d.body_hash AND i.target_kind='group' AND i.additions+i.updates+i.removals=0) AND NOT EXISTS(SELECT 1 FROM app_voice_group_write_operations m WHERE m.line_id=d.line_id AND m.user_nonce=d.user_nonce) AND ((d.write_id IS NULL AND d.reply_hash IS NULL AND d.group_id IS NULL AND d.relation_type IS NULL AND d.relation_properties IS NULL) OR EXISTS(SELECT 1 FROM app_voice_relation_writes w WHERE w.id=d.write_id AND w.line_id=d.line_id AND w.user_nonce=d.user_nonce AND w.target_kind='group' AND w.additions+w.updates+w.removals=0 AND ((w.state IN (0,3) AND d.reply_hash IS NULL AND d.group_id IS NULL AND d.relation_type IS NULL AND d.relation_properties IS NULL) OR (w.state IN (1,2) AND w.result_code=0 AND w.request_id IS NOT NULL AND w.base_time IS NOT NULL AND w.update_time IS NOT NULL AND d.reply_hash IS NOT NULL AND d.relation_type IS NOT NULL AND d.relation_properties IS NOT NULL AND ((w.state=1 AND d.group_id IS NOT NULL) OR (w.state=2 AND d.group_id IS NULL)))))) THEN 1 ELSE NULL END FROM app_voice_group_creations d WHERE d.line_id=?1 AND d.user_nonce=?2",params![line,nonce],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?,r.get(5)?))).optional().map_err(|_|STORAGE)?;
 row.map(|(p,i,w,m,r,h)|{if !(2..=128).contains(&p)||i<=0||!(1..=128).contains(&m)||!matches!(r,0|1)||h!=Some(1)||intent.is_some()&&intent!=Some(i)||write.is_some()&&write!=w{return Err(STORAGE);}Ok(Descriptor{operation:GroupWriteOperation::Create,properties:p as usize})}).transpose()
}
pub(super) fn validate_shared(c:&Connection,line:&str)->Result<(),&'static str>{
 let bad:bool=c.query_row("SELECT EXISTS(SELECT 1 FROM app_voice_group_creations d WHERE d.line_id=?1 AND (NOT EXISTS(SELECT 1 FROM app_voice_relation_intents i WHERE i.id=d.intent_id AND i.body_hash=d.body_hash AND i.line_id=d.line_id AND i.user_nonce=d.user_nonce AND i.target_kind='group' AND i.additions+i.updates+i.removals=0 AND ((i.state IN(0,2) AND i.write_id IS NULL AND d.write_id IS NULL) OR(i.state=1 AND i.write_id=d.write_id))) OR(d.write_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM app_voice_relation_writes w WHERE w.id=d.write_id AND w.line_id=d.line_id AND w.user_nonce=d.user_nonce AND w.target_kind='group' AND w.additions+w.updates+w.removals=0)))) OR EXISTS(SELECT 1 FROM app_voice_relation_intents i WHERE i.line_id=?1 AND i.additions+i.updates+i.removals=0 AND NOT EXISTS(SELECT 1 FROM app_voice_group_creations d WHERE d.line_id=i.line_id AND d.user_nonce=i.user_nonce AND d.intent_id=i.id) AND NOT EXISTS(SELECT 1 FROM app_voice_group_write_operations d WHERE d.line_id=i.line_id AND d.user_nonce=i.user_nonce AND d.intent_id=i.id)) OR EXISTS(SELECT 1 FROM app_voice_relation_writes w WHERE w.line_id=?1 AND w.additions+w.updates+w.removals=0 AND NOT EXISTS(SELECT 1 FROM app_voice_group_creations d WHERE d.line_id=w.line_id AND d.user_nonce=w.user_nonce AND d.write_id=w.id) AND NOT EXISTS(SELECT 1 FROM app_voice_group_write_operations d WHERE d.line_id=w.line_id AND d.user_nonce=w.user_nonce AND d.write_id=w.id)) OR EXISTS(SELECT 1 FROM app_voice_group_creations a JOIN app_voice_group_write_operations b ON a.line_id=b.line_id AND a.user_nonce=b.user_nonce WHERE a.line_id=?1)",[line],|r|r.get(0)).map_err(|_|STORAGE)?;
 let old_bad:bool=c.query_row("SELECT EXISTS(SELECT 1 FROM app_voice_group_write_operations d WHERE d.line_id=?1 AND (d.intent_id IS NULL OR NOT EXISTS(SELECT 1 FROM app_voice_relation_intents i WHERE i.id=d.intent_id AND i.line_id=d.line_id AND i.user_nonce=d.user_nonce AND i.target_kind='group' AND i.additions+i.updates+i.removals=0 AND ((i.state IN(0,2) AND i.write_id IS NULL AND d.write_id IS NULL) OR(i.state=1 AND i.write_id=d.write_id))) OR(d.write_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM app_voice_relation_writes w WHERE w.id=d.write_id AND w.line_id=d.line_id AND w.user_nonce=d.user_nonce AND w.target_kind='group' AND w.additions+w.updates+w.removals=0))))",[line],|r|r.get(0)).map_err(|_|STORAGE)?;
 if bad||old_bad{Err(STORAGE)}else{Ok(())}
}
pub(super) fn commit_result(c:&Connection,line:&str,nonce:&str,write:i64,result:&CreatedReply)->Result<(),&'static str>{
 let group=if result.accepted{Some(result.group.as_slice())}else{None};let n=c.execute("UPDATE app_voice_group_creations SET group_id=?4,reply_hash=?5,relation_type=?6,relation_properties=?7 WHERE line_id=?1 AND user_nonce=?2 AND write_id=?3 AND reply_hash IS NULL AND EXISTS(SELECT 1 FROM app_voice_relation_writes w WHERE w.id=?3 AND w.line_id=?1 AND w.user_nonce=?2 AND w.state=?8)",params![line,nonce,write,group,result.fingerprint.as_slice(),i64::from(result.relation_type),result.relation_properties as i64,if result.accepted{1}else{2}]).map_err(|_|STORAGE)?;if n!=1{return Err(STORAGE);}Ok(())
}
pub(super) fn receipt_matches(c:&Connection,line:&str,nonce:&str,write:i64,input:&CreateInput,result:&CreatedReply)->Result<bool,&'static str>{
 c.query_row("SELECT EXISTS(SELECT 1 FROM app_voice_group_creations d JOIN app_voice_relation_writes w ON d.write_id=w.id AND d.line_id=w.line_id AND d.user_nonce=w.user_nonce WHERE d.line_id=?1 AND d.user_nonce=?2 AND d.write_id=?3 AND w.state=1 AND d.read_properties=1 AND d.body_hash=?4 AND d.group_id=?5 AND d.reply_hash=?6 AND d.relation_type=?7 AND d.relation_properties=?8 AND d.initial_members=?9 AND d.properties=?10)",params![line,nonce,write,input.fingerprint().as_slice(),result.group.as_slice(),result.fingerprint.as_slice(),i64::from(result.relation_type),result.relation_properties as i64,input.initial_members as i64,input.property_count as i64],|r|r.get(0)).map_err(|_|STORAGE)
}
pub(super) fn delete_account(c:&Connection,line:&str)->Result<(),&'static str>{if super::account_store::metadata(c,line)?.is_some(){return Err(STORAGE);}if installed(c)?{c.execute("DELETE FROM app_voice_group_creations WHERE line_id=?1",[line]).map_err(|_|STORAGE)?;}Ok(())}
